#include <pthread.h>
#include <stdio.h>

int main() {
    pthread_key_t key;
    int result = pthread_key_create(&key, NULL);
    if (result == 0) {
        printf("Key created successfully\n");
        pthread_key_delete(key);  // Clean up the key
    } else {
        printf("Failed to create key\n");
    }
    return 0;
}
